line = open("/etc/data-asset/credentials/mobile_nursing_oracle_10_10_10_125.readonly").readline().strip()
u, _, p = line.partition(":")
import oracledb
oracledb.init_oracle_client(lib_dir="/opt/oracle")
conn = oracledb.connect(user=u, password=p, dsn="10.10.10.125:1521/ewell", tcp_connect_timeout=20)
cur = conn.cursor()

print("== 试点前置探查（业务日", BIZ_DAY, "）==")
for t in TARGETS:
    view = "V_" + t
    cur.execute(
        "SELECT COLUMN_NAME FROM ALL_TAB_COLUMNS WHERE OWNER='LUNA_MCS_SDSEY' AND TABLE_NAME=:v",
        {"v": view})
    src = {r[0].upper() for r in cur.fetchall()}
    tset = set(TARGETS[t])
    gap = sorted(tset - src)
    align = "ALIGN_OK" if not gap else "GAP=" + ",".join(gap)
    cur.execute(
        "SELECT COUNT(*) FROM ALL_OBJECTS WHERE OWNER='LUNA_MCS_SDSEY' AND OBJECT_NAME=:v AND OBJECT_TYPE='VIEW'",
        {"v": view})
    is_view = cur.fetchone()[0] == 1
    conn.call_timeout = 60000
    try:
        cur.execute(
            f"SELECT COUNT(*) FROM LUNA_MCS_SDSEY.{view} "
            "WHERE DATETIME >= TO_DATE(:s,'YYYY-MM-DD') AND DATETIME < TO_DATE(:e,'YYYY-MM-DD')",
            {"s": BIZ_DAY, "e": "2026-10-25"})
        wincnt = cur.fetchone()[0]
        print(f"{t}: view={is_view} {align} 目标{len(tset)}列 窗COUNT({BIZ_DAY})={wincnt}")
    except Exception as exc:
        print(f"{t}: view={is_view} {align} 目标{len(tset)}列 窗COUNT=TIMEOUT_OR_ERR({type(exc).__name__}: {str(exc)[:90]})")
        conn.rollback()
conn.call_timeout = 0
conn.close()
print("== 探查结束 ==")
